package org.achievementlabs.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.widget.*;import androidx.core.content.FileProvider;
import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import java.util.*;import java.io.*;
public final class QueueQRActivity extends Activity {
 ArrayList<String> frames;int index;ImageView image;TextView label;CheckBox cycling;Handler handler=new Handler(Looper.getMainLooper());boolean visible;Bitmap current;
 Runnable tick=new Runnable(){public void run(){if(visible){if(cycling.isChecked()){index=(index+1)%frames.size();show();}handler.postDelayed(this,500);}}};
 @Override public void onCreate(Bundle b){super.onCreate(b);frames=getIntent().getStringArrayListExtra("frames");if(frames==null||frames.isEmpty()){finish();return;}ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);scroll.addView(root);label=new TextView(this);label.setTextSize(18);root.addView(label);image=new ImageView(this);image.setAdjustViewBounds(true);root.addView(image,new LinearLayout.LayoutParams(-1,-2));cycling=new CheckBox(this);cycling.setText("Cycle automatically");cycling.setChecked(true);root.addView(cycling);Button prev=new Button(this);prev.setText("Previous");prev.setOnClickListener(v->{index=(index+frames.size()-1)%frames.size();show();});root.addView(prev);Button next=new Button(this);next.setText("Next");next.setOnClickListener(v->{index=(index+1)%frames.size();show();});root.addView(next);Button share=new Button(this);share.setText("Share all QR images");share.setOnClickListener(v->share());root.addView(share);TextView hint=new TextView(this);hint.setText("On the other phone, open Auto Unlock → Saved game queues → Scan queue QR. On PC, import all shared QR images together. Includes queue progress and delays, with no sign-in or event tokens.");root.addView(hint);Button close=new Button(this);close.setText("Done");close.setOnClickListener(v->finish());root.addView(close);setContentView(scroll);show();}
 static Bitmap bitmap(String frame)throws Exception{Map<EncodeHintType,Object> hints=new HashMap<>();hints.put(EncodeHintType.MARGIN,4);hints.put(EncodeHintType.ERROR_CORRECTION,com.google.zxing.qrcode.decoder.ErrorCorrectionLevel.M);BitMatrix bits=new MultiFormatWriter().encode(frame,BarcodeFormat.QR_CODE,650,650,hints);int w=bits.getWidth(),h=bits.getHeight();int[] pixels=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)pixels[y*w+x]=bits.get(x,y)?Color.BLACK:Color.WHITE;return Bitmap.createBitmap(pixels,w,h,Bitmap.Config.ARGB_8888);}
 void show(){try{Bitmap next=bitmap(frames.get(index));image.setImageBitmap(next);if(current!=null)current.recycle();current=next;label.setText("Queue code "+(index+1)+" of "+frames.size());}catch(Exception e){label.setText("Could not render QR. Use the sync file.");}}
 void share(){cycling.setChecked(false);new Thread(()->{try{File dir=new File(getCacheDir(),"queue-qr/"+UUID.randomUUID());if(!dir.mkdirs())throw new IOException();ArrayList<Uri> urls=new ArrayList<>();for(int i=0;i<frames.size();i++){File file=new File(dir,String.format(Locale.ROOT,"Queue-%03d.png",i+1));Bitmap bm=bitmap(frames.get(i));try(FileOutputStream out=new FileOutputStream(file)){bm.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bm.recycle();}urls.add(FileProvider.getUriForFile(this,getPackageName()+".queueqr",file));}runOnUiThread(()->{Intent send=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("image/png").putParcelableArrayListExtra(Intent.EXTRA_STREAM,urls).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);ClipData clip=ClipData.newRawUri("Queue QR",urls.get(0));for(int i=1;i<urls.size();i++)clip.addItem(new ClipData.Item(urls.get(i)));send.setClipData(clip);startActivity(Intent.createChooser(send,"Share queue QR images"));});}catch(Exception e){runOnUiThread(()->label.setText("Could not share QR images. Use the sync file."));}}).start();}
 @Override protected void onResume(){super.onResume();visible=true;handler.postDelayed(tick,500);}@Override protected void onPause(){visible=false;handler.removeCallbacks(tick);super.onPause();}@Override protected void onDestroy(){if(current!=null)current.recycle();super.onDestroy();}
}
